cssCode:
.medical-btn {
  padding: 15px 40px; border-radius: 30px; border: 2px solid #ff007f;
  background: transparent; color: #fff; font-size: 16px; font-weight: bold;
  font-family: sans-serif; cursor: pointer; position: relative; overflow: hidden;
  transition: all 0.3s ease; box-shadow: 0 0 15px rgba(255, 0, 127, 0.3);
}
.medical-btn:hover {
  background: #ff007f; color: #fff; transform: scale(1.05);
  box-shadow: 0 0 30px rgba(255, 0, 127, 0.6);
}

